(function () {
  'use strict';

  const SunCalc = {};

  // 📆 Lever et coucher du soleil avec valeurs de secours
  SunCalc.getTimes = function (date, lat, lon, openWeatherData) {
    let sunrise, sunset;

    if (openWeatherData && openWeatherData.sys) {
      sunrise = new Date(openWeatherData.sys.sunrise * 1000);
      sunset = new Date(openWeatherData.sys.sunset * 1000);
} else {
      const year = date.getFullYear();
      const month = date.getMonth();
      const day = date.getDate();
      sunrise = new Date(year, month, day, 6, 0, 0);   // 6h00
      sunset = new Date(year, month, day, 18, 0, 0);   // 18h00
}

    return {
      sunrise,
      sunset,
      source: openWeatherData? "openweathermap": "fallback"
};
};

  // ☀ Position du soleil sur une trajectoire stylisée
  SunCalc.getPosition = function (date, lat, lon, openWeatherData) {
    const times = SunCalc.getTimes(date, lat, lon, openWeatherData);
    const now = date.getTime();
    const dayLength = times.sunset - times.sunrise;
    const timeSinceSunrise = now - times.sunrise;

    const progress = Math.max(0, Math.min(1, timeSinceSunrise / dayLength));

    const width = 1920;
    const height = 1080;
    const yMin = 851;
    const yMax = 300;
    const verticalOffset = 695;
    const horizontalOffset = 200;

    const x = width * progress ;
    const y = yMin - (yMin - yMax) * 4 * progress * (1 - progress);

    return {
      azimuth: (x / width) * Math.PI * 2 - 2.4,
      altitude: 1 - (y / height) * 2 + 1.15
};
};

  // 🌙 Position de la lune (décalée de 12h)
  SunCalc.getMoonPosition = function (date, lat, lon, openWeatherData) {
    const shiftedDate = new Date(date.getTime() + 12 * 60 * 60 * 1000);
    const position = SunCalc.getPosition(shiftedDate, lat, lon, openWeatherData);
    return {
...position,
      distance: 384400,
      parallacticAngle: 0
};
};

  // 👁 Visibilité des astres
  SunCalc.getVisibility = function (date, lat, lon, openWeatherData) {
    const times = SunCalc.getTimes(date, lat, lon, openWeatherData);
    const now = date.getTime();

    const sunriseTime = times.sunrise.getTime();
    const sunsetTime = times.sunset.getTime();

    return {
      sunVisible: now>= sunriseTime && now <= sunsetTime,
      moonVisible: now < sunriseTime || now> sunsetTime,
      source: times.source
};
};

  // Export
  if (typeof exports === 'object' && typeof module!== 'undefined') {
    module.exports = SunCalc;
} else {
    window.SunCalc = SunCalc;
}
})();